
// ======================================
// PROJETO: SISTEMA DE ESTOQUE
// ======================================

// Array para armazenar os produtos
let produtos = [];

// Gerador de códigos
let geradorDeCodigo = 0;


// ======================================
// CADASTRAR PRODUTO
// ======================================

function cadastrarProduto() {

    let descricao = document.getElementById("descricao").value;

        let quantidade = Number(
                document.getElementById("quantidade").value
                    );

                        let valor = Number(
                                document.getElementById("valor").value
                                    );

                                        if (descricao.trim() === "") {
                                                alert("Digite o nome do produto!");
                                                        return;
                                                            }

                                                                if (
                                                                        document.getElementById("quantidade").value === "" ||
                                                                                !Number.isInteger(quantidade) ||
                                                                                        quantidade < 0
                                                                                            ) {
                                                                                                    alert("Digite uma quantidade válida!");
                                                                                                            return;
                                                                                                                }

                                                                                                                    if (
                                                                                                                            document.getElementById("valor").value === "" ||
                                                                                                                                    !Number.isFinite(valor) ||
                                                                                                                                            valor < 0
                                                                                                                                                ) {
                                                                                                                                                        alert("Digite um valor válido!");
                                                                                                                                                                return;
                                                                                                                                                                    }

                                                                                                                                                                        geradorDeCodigo++;

                                                                                                                                                                            let produto = {
                                                                                                                                                                                    codigo: geradorDeCodigo,
                                                                                                                                                                                            descricao: descricao,
                                                                                                                                                                                                    quantidade: quantidade,
                                                                                                                                                                                                            valor: valor
                                                                                                                                                                                                                };

                                                                                                                                                                                                                    produtos.push(produto);

                                                                                                                                                                                                                        alert("Produto cadastrado com sucesso!");

                                                                                                                                                                                                                            document.getElementById("descricao").value = "";
                                                                                                                                                                                                                                document.getElementById("quantidade").value = "";
                                                                                                                                                                                                                                    document.getElementById("valor").value = "";

                                                                                                                                                                                                                                        listarProdutos();
                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                        // ======================================
                                                                                                                                                                                                                                        // LISTAR PRODUTOS
                                                                                                                                                                                                                                        // ======================================

                                                                                                                                                                                                                                        function listarProdutos() {

                                                                                                                                                                                                                                            let lista = document.getElementById("listaProdutos");

                                                                                                                                                                                                                                                lista.innerHTML = "";

                                                                                                                                                                                                                                                    if (produtos.length === 0) {
                                                                                                                                                                                                                                                            lista.textContent = "Nenhum produto cadastrado.";
                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                            produtos.forEach(function(produto) {

                                                                                                                                                                                                                                                                                    let div = document.createElement("div");

                                                                                                                                                                                                                                                                                            div.className = "produto";

                                                                                                                                                                                                                                                                                                    let titulo = document.createElement("strong");
                                                                                                                                                                                                                                                                                                            titulo.textContent = produto.descricao;

                                                                                                                                                                                                                                                                                                                    let informacoes = document.createElement("p");

                                                                                                                                                                                                                                                                                                                            informacoes.textContent =
                                                                                                                                                                                                                                                                                                                                        "Código: " + produto.codigo +
                                                                                                                                                                                                                                                                                                                                                    " | Quantidade: " + produto.quantidade +
                                                                                                                                                                                                                                                                                                                                                                " | Valor: R$ " + produto.valor.toFixed(2);

                                                                                                                                                                                                                                                                                                                                                                        div.appendChild(titulo);
                                                                                                                                                                                                                                                                                                                                                                                div.appendChild(informacoes);

                                                                                                                                                                                                                                                                                                                                                                                        lista.appendChild(div);

                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                            // ======================================
                                                                                                                                                                                                                                                                                                                                                                                            // BUSCAR PRODUTO
                                                                                                                                                                                                                                                                                                                                                                                            // ======================================

                                                                                                                                                                                                                                                                                                                                                                                            function buscarProduto(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                return produtos.find(function(produto) {
                                                                                                                                                                                                                                                                                                                                                                                                        return produto.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                            // ALTERAR VALOR DO PRODUTO
                                                                                                                                                                                                                                                                                                                                                                                                            // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                            function alterarValor() {

                                                                                                                                                                                                                                                                                                                                                                                                                let codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("codigoValor").value
                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                let novoValor = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("novoValor").value
                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                let produto = buscarProduto(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("novoValor").value === "" ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            !Number.isFinite(novoValor) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    novoValor < 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Digite um valor válido!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produto.valor = novoValor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Valor alterado com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("codigoValor").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("novoValor").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ALTERAR QUANTIDADE DO PRODUTO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function alterarQuantidade() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let codigo = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("codigoQuantidade").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let novaQuantidade = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("novaQuantidade").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let produto = buscarProduto(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("novaQuantidade").value === "" ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                !Number.isInteger(novaQuantidade) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        novaQuantidade < 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Digite uma quantidade válida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.quantidade = novaQuantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Quantidade alterada com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("codigoQuantidade").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("novaQuantidade").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // EVENTOS DOS BOTÕES
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("btnCadastrar")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .addEventListener("click", cadastrarProduto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("btnListar")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .addEventListener("click", listarProdutos);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("btnAlterarValor")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .addEventListener("click", alterarValor);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("btnAlterarQuantidade")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .addEventListener("click", alterarQuantidade);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    